import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Only three previously-hardcoded material range accessors; every original method is retained. */
public final class SourceVisibilityRangeMethods {
 static final String P="local/lito381/server/",N=P+"NativeSourceVisibilityRange";
 static void players(ClassNode c){var types=Map.of(P+"BattleSpellCatalog$EntangleSpell",29,P+"BattleSpellCatalog$CancellationSpell",44,P+"BattleSpellCatalog$MassSlowSpell",76);var ids=new IdentityHashMap<MethodNode,Set<Integer>>();for(var m:c.methods){var values=new HashSet<Integer>();for(var type:types.entrySet()){if(m.desc.contains("L"+type.getKey()+";"))values.add(type.getValue());for(var n:m.instructions)if(n instanceof MethodInsnNode call&&call.owner.equals(type.getKey()))values.add(type.getValue());}ids.put(m,values);}boolean changed;do{changed=false;for(var m:c.methods)for(var n:m.instructions)if(n instanceof InvokeDynamicInsnNode indy)for(var arg:indy.bsmArgs)if(arg instanceof Handle h&&h.getOwner().equals(c.name)){var target=c.methods.stream().filter(v->v.name.equals(h.getName())&&v.desc.equals(h.getDesc())).findFirst().orElse(null);if(target!=null)changed|=ids.get(target).addAll(ids.get(m));}}while(changed);var counts=new TreeMap<Integer,Integer>();for(var m:c.methods)for(var n:m.instructions)if(n instanceof MethodInsnNode call&&call.owner.equals(c.name)&&call.name.equals("targetRange")&&call.desc.equals("(IIII)I")&&!ids.get(m).isEmpty()){if(ids.get(m).size()!=1)throw new AssertionError("ambiguous source distance consumer "+m.name+ids.get(m));int id=ids.get(m).iterator().next();call.owner=N;call.name="distance"+id;counts.merge(id,1,Integer::sum);}for(var m:c.methods)if(ids.get(m).size()==1)for(var node:m.instructions)if(node instanceof MethodInsnNode call&&call.owner.equals("java/lang/Math")&&call.name.equals("max")&&call.desc.equals("(II)I")){var last=FreezeAcceptedMethods.prev(call);if(last instanceof MethodInsnNode abs&&abs.owner.equals("java/lang/Math")&&abs.name.equals("abs")&&abs.desc.equals("(I)I")&&FreezeAcceptedMethods.prev(abs).getOpcode()==ISUB){var prior=FreezeAcceptedMethods.prev(last);int steps=0;while(prior!=null&&steps++<12){if(prior instanceof MethodInsnNode first&&first.owner.equals("java/lang/Math")&&first.name.equals("abs")&&first.desc.equals("(I)I")&&FreezeAcceptedMethods.prev(first).getOpcode()==ISUB)break;prior=FreezeAcceptedMethods.prev(prior);}if(prior!=null&&steps<=12){int id=ids.get(m).iterator().next();m.instructions.remove(last);m.instructions.remove(prior);call.owner=N;call.name="signedDistance"+id;counts.merge(id,1,Integer::sum);}}}if(counts.getOrDefault(44,0)==0)throw new AssertionError("actual44 screen consumer");var original=c.methods.stream().filter(m->m.name.equals("targetRange")&&m.desc.equals("(IIII)I")).findFirst().orElseThrow();var copy=new MethodNode(ACC_STATIC,"nativeSourceVisibilityOriginalDistance",original.desc,original.signature,original.exceptions.toArray(String[]::new));original.accept(copy);c.methods.add(copy);System.out.println("source screen distance ports="+counts);}
 static void patch(ClassNode c){var old=c.methods.stream().filter(m->m.name.equals("maximumRange")&&m.desc.equals("()I")).findFirst().orElseThrow();int access=old.access;old.name="nativeSourceVisibilityOriginalRange";var m=new MethodNode(access,"maximumRange","()I",null,null);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new MethodInsnNode(INVOKEVIRTUAL,c.name,"skillId","()I",false));m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new MethodInsnNode(INVOKEVIRTUAL,c.name,old.name,"()I",false));m.instructions.add(new MethodInsnNode(INVOKESTATIC,N,"value","(II)I",false));m.instructions.add(new InsnNode(IRETURN));c.methods.add(m);}
 public static void main(String[]a)throws Exception{try(var jar=new JarFile(a[1])){for(String type:List.of("EntangleSpell","CancellationSpell","MassSlowSpell","ClientSession")){String name=type.equals("ClientSession")?P+type:P+"BattleSpellCatalog$"+type;var c=FreezeAcceptedMethods.read(jar,name);if(type.equals("ClientSession"))players(c);else patch(c);byte[] bytes=FreezeAcceptedMethods.bytes(c,false);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,bytes);}else try(var out=new JarFile(a[2])){if(!Arrays.equals(bytes,FreezeAcceptedMethods.bytes(FreezeAcceptedMethods.read(out,name),false)))throw new AssertionError(name);}}}System.out.println("PASS three source-static material range accessors and captured native screen distance consumers; original bodies retained");}
}
